import { validationFailed } from './errors.js';
import type { Interval } from './slots.js';

export const MINUTE_IN_MS = 60_000;

export function parseInstant(value: string): Date {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    throw validationFailed('Value is not a valid instant', { value });
  }
  return parsed;
}

/** Parses a half-open range and rejects it unless it moves forward in time. */
export function parseRange(
  start: string,
  end: string,
  startField = 'startsAt',
  endField = 'endsAt',
): Interval {
  const startsAt = parseInstant(start);
  const endsAt = parseInstant(end);
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed(`${endField} must be after ${startField}`, {
      [startField]: start,
      [endField]: end,
    });
  }
  return { startsAt, endsAt };
}

export function durationMinutes(start: Date, end: Date): number {
  return Math.round((end.getTime() - start.getTime()) / MINUTE_IN_MS);
}

export function isBefore(a: Date, b: Date): boolean {
  return a.getTime() < b.getTime();
}
