import type { Booking, Prisma } from '@prisma/client';
import { prisma } from '../../db/client.js';
import type { Interval } from '../../shared/slots.js';
import { BOOKING_ACTIVE } from './schema.js';

/** Either the root client or an interactive transaction client. */
export type Client = Prisma.TransactionClient;

export interface BookingData {
  roomId: string;
  userId: string;
  title: string;
  startsAt: Date;
  endsAt: Date;
}

export interface BookingFilter {
  roomId?: string;
  userId?: string;
  status?: string;
  from?: Date;
  to?: Date;
  limit: number;
  offset: number;
}

export function create(data: BookingData, client: Client = prisma): Promise<Booking> {
  return client.booking.create({ data });
}

/**
 * Finds an active booking of the room that overlaps `interval`.
 * Intervals are half-open, so a booking that starts exactly when another ends fits.
 */
export function findOverlapping(
  roomId: string,
  interval: Interval,
  excludeId?: string,
  client: Client = prisma,
): Promise<Booking | null> {
  return client.booking.findFirst({
    where: {
      roomId,
      status: BOOKING_ACTIVE,
      startsAt: { lt: interval.endsAt },
      endsAt: { gt: interval.startsAt },
      ...(excludeId ? { id: { not: excludeId } } : {}),
    },
    orderBy: { startsAt: 'asc' },
  });
}

/** Every active booking of the given rooms that touches the window, oldest first. */
export function findActiveInWindow(roomIds: string[], window: Interval): Promise<Booking[]> {
