import type { Booking } from '@prisma/client';
import { prisma } from '../../db/client.js';
import {
  AppError,
  batchBookingConflict,
  bookingConflict,
  notFound,
  validationFailed,
  type BatchFailure,
} from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { overlaps, type Interval } from '../../shared/slots.js';
import { parseInstant, parseRange } from '../../shared/time.js';
import { suggestSlots } from '../availability/service.js';
import * as repository from './repository.js';
import { BOOKING_ACTIVE, BOOKING_CANCELLED } from './schema.js';
import type {
  CreateBookingInput,
  CreateBookingsBatchInput,
  ListBookingsInput,
  UpdateBookingInput,
} from './schema.js';

/** Rejects the booking unless the room and the organiser both exist. */
async function ensureReferences(
  client: repository.Client,
  roomIds: string[],
  userIds: string[],
): Promise<void> {
  const wantedRooms = [...new Set(roomIds)];
  const wantedUsers = [...new Set(userIds)];

  const found = await repository.findExistingRoomIds(wantedRooms, client);
  const missingRooms = wantedRooms.filter((id) => !found.some((room) => room.id === id));
  if (missingRooms.length > 0) {
    throw notFound('Room', { roomIds: missingRooms });
  }

  const users = await repository.findExistingUserIds(wantedUsers, client);
  const missingUsers = wantedUsers.filter((id) => !users.some((user) => user.id === id));
  if (missingUsers.length > 0) {
    throw notFound('User', { userIds: missingUsers });
  }
}

/**
 * Turns a bare conflict into an actionable one by attaching the next free slots,
 * so the caller does not have to probe the calendar by hand.
 */
async function withSuggestions(error: unknown, roomId: string, wanted: Interval): Promise<unknown> {
  if (!(error instanceof AppError) || error.code !== 'BOOKING_CONFLICT') {
    return error;
  }
  const conflictingBookingId = error.details.conflictingBookingId;
  if (typeof conflictingBookingId !== 'string') {
    return error;
  }
  return bookingConflict(conflictingBookingId, await suggestSlots(roomId, wanted));
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const interval = parseRange(input.startsAt, input.endsAt);

  try {
    return await prisma.$transaction(async (tx) => {
      await ensureReferences(tx, [input.roomId], [input.userId]);
      const conflict = await repository.findOverlapping(input.roomId, interval, undefined, tx);
      if (conflict) {
        throw bookingConflict(conflict.id);
      }
      return repository.create({ ...input, ...interval }, tx);
    });
  } catch (error) {
    throw await withSuggestions(error, input.roomId, interval);
  }
}

/**
 * Creates several bookings as a single unit. Either every entry fits or nothing
 * is written and the response lists every problem at once, each with alternatives.
 */
export async function createBookings(input: CreateBookingsBatchInput): Promise<Booking[]> {
  const entries = input.bookings.map((booking, index) => ({
    index,
    input: booking,
    interval: parseRange(booking.startsAt, booking.endsAt),
  }));

  const failures: BatchFailure[] = [];
  for (const entry of entries) {
    const clash = entries.find(
      (other) =>
        other.index < entry.index &&
        other.input.roomId === entry.input.roomId &&
        overlaps(other.interval, entry.interval),
    );
    if (clash) {
      failures.push({
        index: entry.index,
        conflictsWithIndex: clash.index,
        message: `Overlaps entry ${clash.index} of this request, which books the same room`,
      });
    }
  }
  if (failures.length > 0) {
    throw batchBookingConflict(failures);
  }

  try {
    return await prisma.$transaction(async (tx) => {
      await ensureReferences(
        tx,
        entries.map((entry) => entry.input.roomId),
        entries.map((entry) => entry.input.userId),
      );

      const clashes: BatchFailure[] = [];
      for (const entry of entries) {
        const conflict = await repository.findOverlapping(
          entry.input.roomId,
          entry.interval,
          undefined,
          tx,
        );
        if (conflict) {
          clashes.push({
            index: entry.index,
            conflictingBookingId: conflict.id,
            message: 'Room is already booked for this period',
          });
        }
      }
      if (clashes.length > 0) {
        throw batchBookingConflict(clashes);
      }

      const created: Booking[] = [];
      for (const entry of entries) {
        created.push(await repository.create({ ...entry.input, ...entry.interval }, tx));
      }
      return created;
    });
  } catch (error) {
    throw await withBatchSuggestions(error, entries);
  }
}

async function withBatchSuggestions(
  error: unknown,
  entries: { index: number; input: CreateBookingInput; interval: Interval }[],
): Promise<unknown> {
  if (!(error instanceof AppError) || error.code !== 'BOOKING_CONFLICT') {
    return error;
  }
  const failures = error.details.failures;
  if (!Array.isArray(failures)) {
    return error;
  }

  return batchBookingConflict(
    await Promise.all(
      (failures as BatchFailure[]).map(async (failure) => {
        const entry = entries[failure.index];
        if (!entry) return failure;
        return { ...failure, suggestions: await suggestSlots(entry.input.roomId, entry.interval) };
      }),
    ),
  );
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await repository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await repository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
  });
  return paginated(data, total, limit, offset);
}

export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const current = await getBooking(id);
  const roomId = input.roomId ?? current.roomId;
  const interval: Interval = {
    startsAt: input.startsAt !== undefined ? parseInstant(input.startsAt) : current.startsAt,
    endsAt: input.endsAt !== undefined ? parseInstant(input.endsAt) : current.endsAt,
  };
  if (interval.startsAt.getTime() >= interval.endsAt.getTime()) {
    throw validationFailed('endsAt must be after startsAt', {
      startsAt: interval.startsAt.toISOString(),
      endsAt: interval.endsAt.toISOString(),
    });
  }

  try {
    return await prisma.$transaction(async (tx) => {
      await ensureReferences(
        tx,
        input.roomId !== undefined ? [input.roomId] : [],
        input.userId !== undefined ? [input.userId] : [],
      );

      // A cancelled booking holds no slot, so moving it can never clash.
      if (current.status === BOOKING_ACTIVE) {
        const conflict = await repository.findOverlapping(roomId, interval, id, tx);
        if (conflict) {
          throw bookingConflict(conflict.id);
        }
      }

      return repository.update(
        id,
        {
          ...(input.roomId !== undefined ? { roomId: input.roomId } : {}),
          ...(input.userId !== undefined ? { userId: input.userId } : {}),
          ...(input.title !== undefined ? { title: input.title } : {}),
          ...(input.startsAt !== undefined ? { startsAt: interval.startsAt } : {}),
          ...(input.endsAt !== undefined ? { endsAt: interval.endsAt } : {}),
        },
        tx,
      );
    });
  } catch (error) {
    throw await withSuggestions(error, roomId, interval);
  }
}

export async function cancelBooking(id: string): Promise<Booking> {
  const booking = await getBooking(id);
  if (booking.status === BOOKING_CANCELLED) {
    return booking;
  }
  return repository.updateStatus(id, BOOKING_CANCELLED);
}

export async function deleteBooking(id: string): Promise<void> {
  await getBooking(id);
  await repository.remove(id);
}
