describe('ranges', () => {
  it('parses a range that moves forward', () => {
    const range = parseRange('2030-01-01T10:00:00.000Z', '2030-01-01T11:00:00.000Z');
    expect(durationMinutes(range.startsAt, range.endsAt)).toBe(60);
  });

  it('rejects a range that ends before it starts', () => {
    expect(() =>
      parseRange('2030-01-01T11:00:00.000Z', '2030-01-01T10:00:00.000Z'),
    ).toThrowError(AppError);
  });

  it('rejects a range of zero length', () => {
    expect(() =>
      parseRange('2030-01-01T10:00:00.000Z', '2030-01-01T10:00:00.000Z'),
    ).toThrowError(AppError);
  });

  it('names the fields it was given in the message', () => {
    expect(() => parseRange('2030-01-02T00:00:00Z', '2030-01-01T00:00:00Z', 'from', 'to')).toThrow(
      /to must be after from/,
    );
  });
});

const at = (hour: number): Date => new Date(Date.UTC(2030, 0, 1, hour));
const span = (from: number, to: number) => ({ startsAt: at(from), endsAt: at(to) });
const readable = (intervals: { startsAt: Date; endsAt: Date }[]) =>
  intervals.map((i) => [i.startsAt.getUTCHours(), i.endsAt.getUTCHours()]);

describe('overlaps', () => {
  it('sees a partial overlap on the left', () => {
    expect(overlaps(span(9, 11), span(10, 12))).toBe(true);
  });

  it('sees a partial overlap on the right', () => {
    expect(overlaps(span(11, 13), span(10, 12))).toBe(true);
  });

  it('sees an interval that swallows another', () => {
    expect(overlaps(span(8, 18), span(10, 12))).toBe(true);
  });

  it('sees an interval nested inside another', () => {
    expect(overlaps(span(10, 11), span(9, 12))).toBe(true);
  });

  it('treats touching intervals as free', () => {
    expect(overlaps(span(9, 10), span(10, 11))).toBe(false);
    expect(overlaps(span(10, 11), span(9, 10))).toBe(false);
  });

  it('treats separate intervals as free', () => {
    expect(overlaps(span(8, 9), span(14, 15))).toBe(false);
  });
});

describe('mergeIntervals', () => {
  it('collapses overlapping intervals', () => {
    expect(readable(mergeIntervals([span(9, 11), span(10, 12)]))).toEqual([[9, 12]]);
  });

  it('collapses touching intervals', () => {
    expect(readable(mergeIntervals([span(9, 10), span(10, 11)]))).toEqual([[9, 11]]);
  });

  it('keeps a nested interval from extending the outer one', () => {
    expect(readable(mergeIntervals([span(8, 18), span(10, 12)]))).toEqual([[8, 18]]);
  });

  it('sorts intervals given out of order', () => {
    expect(readable(mergeIntervals([span(14, 15), span(8, 9)]))).toEqual([
      [8, 9],
      [14, 15],
    ]);
  });
});

describe('freeSlots', () => {
  it('returns the whole window when nothing is booked', () => {
    expect(readable(freeSlots(span(8, 18), []))).toEqual([[8, 18]]);
  });

  it('carves the gaps around the bookings', () => {
    expect(readable(freeSlots(span(8, 18), [span(9, 10), span(14, 16)]))).toEqual([
      [8, 9],
      [10, 14],
      [16, 18],
    ]);
  });

  it('clips bookings that stick out of the window', () => {
    expect(readable(freeSlots(span(8, 18), [span(6, 9), span(17, 20)]))).toEqual([[9, 17]]);
  });

  it('returns nothing when the window is fully booked', () => {
    expect(freeSlots(span(8, 18), [span(7, 19)])).toEqual([]);
  });

  it('ignores bookings that fall outside the window', () => {
    expect(readable(freeSlots(span(8, 18), [span(2, 4), span(20, 22)]))).toEqual([[8, 18]]);
  });

  it('drops gaps shorter than the wanted duration', () => {
    const slots = freeSlots(span(8, 18), [span(9, 10), span(11, 17)], 120 * 60_000);
    expect(readable(slots)).toEqual([[17, 18]]);
  });

  it('keeps a gap that matches the wanted duration exactly', () => {
    const slots = freeSlots(span(8, 18), [span(10, 18)], 120 * 60_000);
    expect(readable(slots)).toEqual([[8, 10]]);
  });

  it('never returns a zero-length gap between touching bookings', () => {
    expect(freeSlots(span(9, 11), [span(9, 10), span(10, 11)])).toEqual([]);
  });
});
