    const [failure] = response.json().error.details.failures;
    expect(failure.conflictingBookingId).toEqual(expect.any(String));
    expect(failure.suggestions[0].durationMinutes).toBe(60);
  });

  it('rejects a batch whose own entries fight over the same room', async () => {
    const response = await batch([entry(24, 26, 'A'), entry(25, 27, 'B')]);
    expect(response.statusCode).toBe(409);
    const [failure] = response.json().error.details.failures;
    expect(failure.index).toBe(1);
    expect(failure.conflictsWithIndex).toBe(0);
    expect(await countBookings()).toBe(0);
  });

  it('allows entries at the same time in different rooms', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(24, 25, 'B', otherRoomId)]);
    expect(response.statusCode).toBe(201);
  });

  it('allows entries that touch without overlapping', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(25, 26, 'B')]);
    expect(response.statusCode).toBe(201);
  });

  it('rejects a batch holding an invalid period', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(27, 26, 'Backwards')]);
    expect(response.statusCode).toBe(400);
    expect(await countBookings()).toBe(0);
  });

  it('writes nothing when a batch names a room that does not exist', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(26, 27, 'B', 'missing-room')]);
    expect(response.statusCode).toBe(404);
    expect(await countBookings()).toBe(0);
  });

  it('rejects an empty batch', async () => {
    expect((await batch([])).statusCode).toBe(400);
  });

  it('rejects a batch larger than the allowed size', async () => {
    const entries = Array.from({ length: 51 }, (_, i) => entry(24 + i * 2, 25 + i * 2, `M${i}`));
    expect((await batch(entries)).statusCode).toBe(400);
  });
});
