describe('booking conflicts', () => {
  let app: FastifyInstance;
  let roomId: string;
  let otherRoomId: string;
  let userId: string;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(async () => {
    await resetDb();
    roomId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Aurora', capacity: 6 } })
    ).json().id;
    otherRoomId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Borealis', capacity: 4 } })
    ).json().id;
    userId = (
      await app.inject({
        method: 'POST',
        url: '/users',
        payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
      })
    ).json().id;
  });

  function payload(startHours: number, endHours: number, title = 'Sync', room = roomId) {
    return {
      roomId: room,
      userId,
      title,
      startsAt: inHours(startHours),
      endsAt: inHours(endHours),
    };
  }

  const book = (s: number, e: number, title = 'Sync', room = roomId) =>
    app.inject({ method: 'POST', url: '/bookings', payload: payload(s, e, title, room) });

  const batch = (bookings: unknown[]) =>
    app.inject({ method: 'POST', url: '/bookings/batch', payload: { bookings } });

  it('rejects a booking that starts before an active one and runs into it', async () => {
    await book(24, 25);
    const response = await book(23.5, 24.5, 'Left overlap');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a booking that swallows an active one', async () => {
    await book(24, 25);
    const response = await book(23, 26, 'Envelope');
    expect(response.statusCode).toBe(409);
  });

  it('rejects a booking with the exact same period', async () => {
    await book(24, 25);
    expect((await book(24, 25, 'Same')).statusCode).toBe(409);
  });

  it('still allows the same period in a different room', async () => {
    await book(24, 25);
    expect((await book(24, 25, 'Elsewhere', otherRoomId)).statusCode).toBe(201);
  });

  it('rejects a booking that ends before it starts', async () => {
    const response = await book(25, 24, 'Backwards');
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects a booking of zero length', async () => {
    expect((await book(24, 24, 'Instant')).statusCode).toBe(400);
  });

  it('answers 404 rather than 500 for a room that does not exist', async () => {
    const response = await book(24, 25, 'Ghost', 'missing-room');
    expect(response.statusCode).toBe(404);
    expect(response.json().error.code).toBe('NOT_FOUND');
  });

  it('answers 404 for a user that does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { ...payload(24, 25), userId: 'missing-user' },
    });
    expect(response.statusCode).toBe(404);
  });

  it('offers free slots of the same length when it refuses a booking', async () => {
    await book(24, 26);
    const response = await book(24, 25, 'Wants an hour');
    expect(response.statusCode).toBe(409);

    const [first] = response.json().error.details.suggestions;
    expect(first.durationMinutes).toBe(60);
    expect(new Date(first.startsAt).toISOString()).toBe(new Date(inHours(26)).toISOString());
  });

  it('skips gaps too short for the booking it is suggesting for', async () => {
    await book(24, 25);
    await book(25.5, 30);
    const response = await book(24, 25, 'Needs a full hour');

    const suggestions = response.json().error.details.suggestions;
    expect(suggestions.length).toBeGreaterThan(0);
    // The 30 minute gap at hour 25 cannot host a one hour meeting.
    expect(new Date(suggestions[0].startsAt).getTime()).toBeGreaterThanOrEqual(
      new Date(inHours(30)).getTime(),
    );
  });

  it('does not suggest anything when the room is free again right away', async () => {
    const first = await book(24, 25);
    const response = await book(24, 25, 'Clash');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('leaves no booking behind when it refuses one', async () => {
    await book(24, 25);
    await book(23.5, 24.5, 'Rejected');
    const list = await app.inject({ method: 'GET', url: `/bookings?roomId=${roomId}` });
    expect(list.json().pagination.total).toBe(1);
  });
});

describe('moving a booking', () => {
  let app: FastifyInstance;
  let roomId: string;
  let userId: string;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(async () => {
    await resetDb();
    roomId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Aurora', capacity: 6 } })
    ).json().id;
    userId = (
      await app.inject({
        method: 'POST',
        url: '/users',
        payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
      })
    ).json().id;
  });

  const book = (s: number, e: number, title = 'Sync') =>
    app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId, title, startsAt: inHours(s), endsAt: inHours(e) },
    });

  const move = (id: string, s: number, e: number) =>
    app.inject({
      method: 'PATCH',
      url: `/bookings/${id}`,
      payload: { startsAt: inHours(s), endsAt: inHours(e) },
    });

  it('refuses to move a booking on top of another one', async () => {
    const first = await book(24, 25);
    const second = await book(30, 31, 'Second');
    const response = await move(second.json().id, 24, 25);
    expect(response.statusCode).toBe(409);
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('suggests alternatives when a move is refused', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Second');
    const response = await move(second.json().id, 24, 25);
    expect(response.json().error.details.suggestions.length).toBeGreaterThan(0);
  });

  it('lets a booking keep its own period', async () => {
    const created = await book(24, 25);
    const response = await move(created.json().id, 24, 25);
    expect(response.statusCode).toBe(200);
  });

  it('moves a booking into a free period', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Second');
    const response = await move(second.json().id, 26, 27);
    expect(response.statusCode).toBe(200);
    expect(new Date(response.json().startsAt).toISOString()).toBe(
      new Date(inHours(26)).toISOString(),
    );
  });

  it('rejects a move that would end before it starts', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: inHours(26) },
    });
    expect(response.statusCode).toBe(400);
  });

  it('lets a cancelled booking move onto an active period', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Second');
    await app.inject({ method: 'POST', url: `/bookings/${second.json().id}/cancel` });
    expect((await move(second.json().id, 24, 25)).statusCode).toBe(200);
  });

  it('answers 404 when moving a booking to a room that does not exist', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { roomId: 'missing-room' },
    });
    expect(response.statusCode).toBe(404);
  });
});

describe('booking several rooms at once', () => {
  let app: FastifyInstance;
  let roomId: string;
  let otherRoomId: string;
  let userId: string;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(async () => {
    await resetDb();
    roomId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Aurora', capacity: 6 } })
    ).json().id;
    otherRoomId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Borealis', capacity: 4 } })
    ).json().id;
    userId = (
      await app.inject({
        method: 'POST',
        url: '/users',
        payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
      })
    ).json().id;
  });

  const entry = (s: number, e: number, title = 'Sync', room = roomId) => ({
    roomId: room,
    userId,
    title,
    startsAt: inHours(s),
    endsAt: inHours(e),
  });

  const batch = (bookings: unknown[]) =>
    app.inject({ method: 'POST', url: '/bookings/batch', payload: { bookings } });

  const countBookings = async () =>
    (await app.inject({ method: 'GET', url: '/bookings' })).json().pagination.total;

  it('creates every booking of a batch that fits', async () => {
    const response = await batch([entry(24, 25), entry(26, 27, 'Retro'), entry(24, 25, 'Elsewhere', otherRoomId)]);
    expect(response.statusCode).toBe(201);
    expect(response.json().data).toHaveLength(3);
    expect(await countBookings()).toBe(3);
  });

  it('keeps the order of the request in the response', async () => {
    const response = await batch([entry(30, 31, 'Third'), entry(24, 25, 'First')]);
    expect(response.json().data.map((b: { title: string }) => b.title)).toEqual(['Third', 'First']);
  });

  it('writes nothing when one entry clashes with an existing booking', async () => {
    await app.inject({ method: 'POST', url: '/bookings', payload: entry(24, 25) });
    const response = await batch([entry(30, 31, 'Fine'), entry(24.5, 25.5, 'Clashes')]);
    expect(response.statusCode).toBe(409);
    expect(await countBookings()).toBe(1);
  });

  it('reports every clashing entry at once instead of one per attempt', async () => {
    await app.inject({ method: 'POST', url: '/bookings', payload: entry(24, 25) });
    await app.inject({ method: 'POST', url: '/bookings', payload: entry(30, 31, 'Other') });

    const response = await batch([entry(24, 25, 'A'), entry(40, 41, 'B'), entry(30, 31, 'C')]);
    expect(response.statusCode).toBe(409);
    expect(response.json().error.details.failures.map((f: { index: number }) => f.index)).toEqual([
      0, 2,
    ]);
  });

  it('offers alternatives for each rejected entry', async () => {
    await app.inject({ method: 'POST', url: '/bookings', payload: entry(24, 26) });
    const response = await batch([entry(24, 25, 'A')]);
    const [failure] = response.json().error.details.failures;
    expect(failure.conflictingBookingId).toEqual(expect.any(String));
    expect(failure.suggestions[0].durationMinutes).toBe(60);
  });

  it('rejects a batch whose own entries fight over the same room', async () => {
    const response = await batch([entry(24, 26, 'A'), entry(25, 27, 'B')]);
    expect(response.statusCode).toBe(409);
    const [failure] = response.json().error.details.failures;
    expect(failure.index).toBe(1);
    expect(failure.conflictsWithIndex).toBe(0);
    expect(await countBookings()).toBe(0);
  });

  it('allows entries at the same time in different rooms', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(24, 25, 'B', otherRoomId)]);
    expect(response.statusCode).toBe(201);
  });

  it('allows entries that touch without overlapping', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(25, 26, 'B')]);
    expect(response.statusCode).toBe(201);
  });

  it('rejects a batch holding an invalid period', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(27, 26, 'Backwards')]);
    expect(response.statusCode).toBe(400);
    expect(await countBookings()).toBe(0);
  });

  it('writes nothing when a batch names a room that does not exist', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(26, 27, 'B', 'missing-room')]);
    expect(response.statusCode).toBe(404);
    expect(await countBookings()).toBe(0);
  });

  it('rejects an empty batch', async () => {
    expect((await batch([])).statusCode).toBe(400);
  });

  it('rejects a batch larger than the allowed size', async () => {
    const entries = Array.from({ length: 51 }, (_, i) => entry(24 + i * 2, 25 + i * 2, `M${i}`));
    expect((await batch(entries)).statusCode).toBe(400);
  });
});

